{noformat}import ExternalRequestClient, {
    ExternalRequestClientParser,
    ExternalRequestClientResponse,
    ExternalRequestHeaders,
    ExternalRequestParams,
} from "@taxify/nodejs-common/lib/httpOutgoing/ExternalRequestClient";
import Context from "@taxify/nodejs-common/lib/logger/Context";
import {ExternalRequestClientParserJson} from "@taxify/nodejs-common/lib/httpOutgoing/ExternalRequestParser/ExternalRequestClientParserJson";
import {OpenAIClientConfig} from "../config/Config";
import {OpenAIExternalApiValidator} from "../../gen/validators/externalApi/OpenAIExternalApiValidator";
import Response, {CommonResponseCodes, SuccessResponse} from "@taxify/nodejs-common/lib/response/Response";
import {BoltError} from "@taxify/nodejs-common/lib/async/error/BoltError";

export class OpenAIExternalApi extends ExternalRequestClient {
    private readonly parser: ExternalRequestClientParser<CompletionRequest, ChatCompletionResponse, any>;

    constructor(private readonly config: OpenAIClientConfig, validator: OpenAIExternalApiValidator.AutomaticValidator) {
        super("openai", config, undefined, validator);
        this.parser = new ExternalRequestClientParserJson<CompletionRequest, ChatCompletionResponse, any>();
    }

    public async getCompletion(ctx: Context, input: CompletionRequest): Promise<string> {
        const response = await this.doGetCompletion(ctx, {Authorization: `Bearer ${this.config.api_key}`}, {}, input);

        if (Response.isNotOk(response.response_object)) {
            throw BoltError.errorResponse(response.response_object);
        }

        if (response.api_status !== 200 || !response.response_object.data) {
            throw BoltError.code(CommonResponseCodes.SERVER_ERROR, "Invalid OpenAI response for completion");
        }

        return (response.response_object as SuccessResponse<ChatCompletionResponse>).data.choices[0].message.content;
    }

    private async doGetCompletion(
        ctx: Context,
        headers: ExternalRequestHeaders,
        params: ExternalRequestParams,
        input: CompletionRequest,
    ): Promise<ExternalRequestClientResponse<ChatCompletionResponse, string>> {
        return this.sendAsyncPostWithHeadersParamsAndParserAndAllErrors(
            ctx,
            "completions",
            "/v1/chat/completions",
            headers,
            params,
            input,
            this.parser,
            {timeout_ms: 60000},
        );
    }
}

export interface CompletionRequest {
    model: string;
    messages: Message[];
}

export interface Message {
    role: Role;
    content: string;
}

export enum Role {
    SYSTEM = "system",
    USER = "user",
}

export interface ChatCompletionResponse {
    choices: Choice[];
}

export interface Choice {
    index: number;
    message: AssistantMessage;
    finish_reason: string;
}

export interface AssistantMessage {
    role: "assistant";
    content: string;
}{noformat}

